               l.indexOf('Script started') === -1 &&
               l.indexOf('Script done') === -1 &&
               l.indexOf('COMMAND=') === -1 &&
               l.indexOf('COMMAND_EXIT_CODE=') === -1;
    }).join('').trim();
}

