    try {
        const raw = outputFiles.readOutputFile(path, {});
        return (raw && raw.trim()) ? JSON.parse(raw) : null;
    } catch (e) {
        return null;
    }
}

function hasCodeGraphUsage() {
    try {
        const raw = file_read({ path: '.dmtools/codegraph-usage.log' });
        return !!(raw && raw.trim());
    } catch (e) {
        return false;
    }
}

/**
